select *
from orders
where id not in (select order_id from order_items where unit_price <= 286.0) and amount <= 1231.3;

SELECT oi.*
FROM order_items oi
WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.id = oi.product_id);

SELECT s.*
FROM subscriptions s
WHERE NOT EXISTS (SELECT 1 FROM customers c WHERE c.id = s.customer_id AND c.email IN ('frank@company.co', 'jack@startup.io'));

select *
from inventory
where product_id in (select id from products where stock_qty <= 344);

select *
from sessions s
where not exists (select * from web_events we where we.session_id = s.id and we.duration_sec >= 339);

SELECT *
FROM sessions s
WHERE NOT EXISTS (SELECT 1 FROM web_events we WHERE we.session_id = s.id AND we.page <> '/search');

SELECT *
FROM accounts a
WHERE EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.merchant IN ('Amazon', 'Grab'));

SELECT c.*
FROM customers c
WHERE NOT EXISTS (SELECT * FROM subscriptions s WHERE s.customer_id = c.id AND s.status = 'EXPIRED');

SELECT *
FROM employees
WHERE job_title <> 'Engineer' AND dept_id NOT IN (SELECT id FROM departments WHERE budget >= 2100894.8);

SELECT *
FROM transactions t
WHERE EXISTS (SELECT 1 FROM accounts a WHERE a.id = t.account_id AND a.balance >= 27024.2) AND t.merchant = 'Grab';

SELECT a.*
FROM accounts a
WHERE EXISTS (SELECT * FROM transactions t WHERE t.account_id = a.id AND t.merchant IN ('Shell', '7-Eleven')) AND a.status IN ('CLOSED', 'OPEN');

SELECT *
FROM accounts a
WHERE EXISTS (SELECT 1 FROM customers c WHERE c.id = a.customer_id AND c.email = 'IVY@GMAIL.COM');

SELECT *
FROM suppliers s
WHERE s.id NOT IN (SELECT p.supplier_id FROM products p WHERE p.brand <> 'Acme' AND p.supplier_id IS NOT NULL);

SELECT o.*
FROM orders o
WHERE o.id NOT IN (SELECT s.order_id FROM shipments s WHERE s.status <> 'RETURNED' AND s.order_id IS NOT NULL);

SELECT *
FROM inventory
WHERE store_id NOT IN (SELECT id FROM stores WHERE region <> 'Central');

SELECT *
FROM suppliers s
WHERE NOT EXISTS (SELECT * FROM products p WHERE p.supplier_id = s.id AND p.product_name IN ('Laptop Pro 14', 'Running Shoes'));

SELECT *
FROM products p
WHERE p.supplier_id IN (SELECT s.id FROM suppliers s WHERE s.supplier_name = 'Tokyo Traders');

SELECT oi.*
FROM order_items oi
WHERE oi.order_id IN (SELECT o.id FROM orders o WHERE o.amount <= 1111.3);

SELECT *
FROM suppliers s
WHERE s.city = 'Bangkok' AND EXISTS (SELECT 1 FROM products p WHERE p.supplier_id = s.id AND p.price < 480.2);

SELECT *
FROM accounts a
WHERE a.id IN (SELECT t.account_id FROM transactions t WHERE t.txn_type <> 'REFUND');

SELECT *
FROM stores s
WHERE s.sqft < 8971 AND NOT EXISTS (SELECT * FROM store_sales ss WHERE ss.store_id = s.id AND ss.revenue <= 2130.8);

SELECT *
FROM stores
WHERE id NOT IN (SELECT store_id FROM store_sales WHERE revenue < 3083.4);

SELECT *
FROM subscriptions s
WHERE EXISTS (SELECT 1 FROM customers c WHERE c.id = s.customer_id AND c.credit_limit > 14253.1) AND s.status = 'EXPIRED';

SELECT *
FROM inventory
WHERE store_id IN (SELECT id FROM stores WHERE region <> 'Central');

SELECT s.*
FROM sessions s
WHERE NOT EXISTS (SELECT 1 FROM customers c WHERE c.id = s.customer_id AND c.name IN ('FRANK MILLER', 'Henry Ford'));

SELECT *
FROM order_items
WHERE quantity >= 5 AND product_id IS NOT NULL AND product_id NOT IN (SELECT id FROM products WHERE price <= 696.2);

SELECT *
FROM products
WHERE brand = 'Globex' AND supplier_id IN (SELECT id FROM suppliers WHERE rating >= 3.1);

SELECT *
FROM accounts a
WHERE EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.txn_type <> 'REFUND');

SELECT *
FROM products p
WHERE NOT EXISTS (SELECT 1 FROM inventory i WHERE i.product_id = p.id);

SELECT *
FROM stores s
WHERE NOT EXISTS (SELECT 1 FROM inventory i WHERE i.store_id = s.id AND i.quantity <= 193);

SELECT *
FROM suppliers s
WHERE s.id IN (SELECT p.supplier_id FROM products p WHERE p.cost < 307.9);

SELECT *
FROM employees
WHERE dept_id NOT IN (SELECT id FROM departments WHERE dept_name IN ('Marketing', 'HR'));

select *
from orders
where customer_id is not null and customer_id not in (select id from customers where segment <> 'Consumer');

select *
from products
where price >= 806.6 and id in (select product_id from order_items where unit_price <= 148.6);

SELECT *
FROM employees e
WHERE e.dept_id NOT IN (SELECT d.id FROM departments d) AND e.email = 'alice@gmail.com';
